"""In-place foreach division of a tensor list by a scalar list (Triton).

Reference semantics (aten::_foreach_div_.ScalarList):
  for each i: T_i[idx] /= s_i   (IEEE true division, scalar broadcast)
  - strictly in-place, same storages, returns None
  - arbitrary (affine) strides, no copies
  - fp16/bf16 computed through fp32 opmath and rounded back

Launch structure: one Triton launch per call for the common case where several
contiguous tensors share a dtype (2-D grid: tile x tensor index, per-program
pointer/scalar/size selection inside the kernel).  Falls back to one launch per
tensor for strided tensors, mixed dtypes and overlapping storages.
"""

import torch
import triton
import triton.language as tl

_MISSING = object()

_FLAT_BLOCK = 4096
_STRIDED_BLOCK = 2048
_KMAX = 8


@triton.jit
def _div_flat(X, S, N, CAST: tl.constexpr, BLOCK: tl.constexpr):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    x = tl.load(X + offs, mask=mask, other=0.0)
    if CAST:
        y = x.to(tl.float32) / S
    else:
        y = x / S
    tl.store(X + offs, y.to(X.dtype.element_ty), mask=mask)


@triton.jit
def _fused_body(X, S, offs, N, CAST: tl.constexpr):
    mask = offs < N
    x = tl.load(X + offs, mask=mask, other=0.0)
    if CAST:
        y = x.to(tl.float32) / S
    else:
        y = x / S
    tl.store(X + offs, y.to(X.dtype.element_ty), mask=mask)


@triton.jit
def _div_fused(
    X0,
    X1,
    X2,
    X3,
    X4,
    X5,
    X6,
    X7,
    S0,
    S1,
    S2,
    S3,
    S4,
    S5,
    S6,
    S7,
    N0,
    N1,
    N2,
    N3,
    N4,
    N5,
    N6,
    N7,
    K: tl.constexpr,
    CAST: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    _fused_body(X0, S0, offs, N0, CAST)
    if K > 1:
        _fused_body(X1, S1, offs, N1, CAST)
    if K > 2:
        _fused_body(X2, S2, offs, N2, CAST)
    if K > 3:
        _fused_body(X3, S3, offs, N3, CAST)
    if K > 4:
        _fused_body(X4, S4, offs, N4, CAST)
    if K > 5:
        _fused_body(X5, S5, offs, N5, CAST)
    if K > 6:
        _fused_body(X6, S6, offs, N6, CAST)
    if K > 7:
        _fused_body(X7, S7, offs, N7, CAST)


@triton.jit
def _div_strided(
    X,
    S,
    N,
    OFF,
    sh0,
    sh1,
    sh2,
    sh3,
    st0,
    st1,
    st2,
    st3,
    CAST: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    offs = pid * BLOCK + tl.arange(0, BLOCK)
    mask = offs < N
    i3 = offs % sh3
    r = offs // sh3
    i2 = r % sh2
    r = r // sh2
    i1 = r % sh1
    i0 = r // sh1
    addr = OFF + i0 * st0 + i1 * st1 + i2 * st2 + i3 * st3
    x = tl.load(X + addr, mask=mask, other=0.0)
    if CAST:
        y = x.to(tl.float32) / S
    else:
        y = x / S
    tl.store(X + addr, y.to(X.dtype.element_ty), mask=mask)


def _collapse(shape, strides):
    """Drop size-1 dims and merge adjacent dims that stay affine."""
    merged = []
    for sz, st in zip(shape, strides):
        if sz == 1:
            continue
        if merged and merged[-1][1] == sz * st:
            merged[-1][0] *= sz
            merged[-1][1] = st
        else:
            merged.append([sz, st])
    return merged


def _scalar_value(s):
    if isinstance(s, torch.Tensor):
        if s.numel() != 1:
            raise RuntimeError(
                "_foreach_div_ expected a list of scalars, got a tensor with "
                "more than one element"
            )
        return float(s.item())
    if isinstance(s, (bool, int, float)):
        return float(s)
    raise RuntimeError(
        "foreach_div_ expects a Number or a sequence of Numbers as the divisor"
    )


def _plan_one(t, s):
    """Metadata-only classification of one (tensor, scalar) pair."""
    numel = t.numel()
    if numel == 0:
        return None
    if not t.is_floating_point():
        raise RuntimeError(
            "result type Float can't be cast to the desired output type "
            + str(t.dtype).replace("torch.", "")
        )
    shape = t.shape
    strides = t.stride()
    span = 1
    for sz, st in zip(shape, strides):
        if sz > 1 and st == 0:
            raise RuntimeError(
                "unsupported operation: more than one element of the written-to "
                "tensor refers to a single memory location."
            )
        span += (sz - 1) * st
    merged = _collapse(shape, strides)
    if not merged:
        merged = [[1, 1]]
    flat = len(merged) == 1 and merged[0][1] == 1
    return (t, s, numel, flat, merged, t.data_ptr(), span * t.element_size())


def _alias_free(plans):
    spans = sorted((p[5], p[5] + p[6]) for p in plans)
    for i in range(1, len(spans)):
        if spans[i][0] < spans[i - 1][1]:
            return False
    return True


def _launch_flat(t, s, numel, cast):
    grid = ((numel + _FLAT_BLOCK - 1) // _FLAT_BLOCK,)
    _div_flat[grid](t, s, numel, CAST=cast, BLOCK=_FLAT_BLOCK)


def _launch_fused(group, cast):
    k = len(group)
    pad_t = group[0][0]
    ptrs = [g[0] for g in group] + [pad_t] * (_KMAX - k)
    scal = [g[1] for g in group] + [1.0] * (_KMAX - k)
    sizes = [g[2] for g in group] + [0] * (_KMAX - k)
    tiles = 0
    for g in group:
        t = (g[2] + _FLAT_BLOCK - 1) // _FLAT_BLOCK
        if t > tiles:
            tiles = t
    grid = (tiles,)
    _div_fused[grid](*(ptrs + scal + sizes), K=k, CAST=cast, BLOCK=_FLAT_BLOCK)


def _launch_strided(t, s, numel, dims, off, cast):
    padded = [[1, 0] for _ in range(4 - len(dims))] + [list(d) for d in dims]
    (sh0, st0), (sh1, st1), (sh2, st2), (sh3, st3) = padded
    grid = ((numel + _STRIDED_BLOCK - 1) // _STRIDED_BLOCK,)
    _div_strided[grid](
        t,
        s,
        numel,
        off,
        sh0,
        sh1,
        sh2,
        sh3,
        st0,
        st1,
        st2,
        st3,
        CAST=cast,
        BLOCK=_STRIDED_BLOCK,
    )


def _run_strided(plan):
    t, s, numel, flat, merged, _ptr, _span = plan
    cast = t.dtype != torch.float32
    if len(merged) <= 4:
        _launch_strided(t, s, numel, merged, 0, cast)
        return
    inner = merged[-4:]
    outer = merged[:-4]
    inner_numel = 1
    for sz, _ in inner:
        inner_numel *= sz
    coords = [0] * len(outer)
    while True:
        off = 0
        for c, (sz, st) in zip(coords, outer):
            off += c * st
        _launch_strided(t, s, inner_numel, inner, off, cast)
        k = len(outer) - 1
        while k >= 0:
            coords[k] += 1
            if coords[k] < outer[k][0]:
                break
            coords[k] = 0
            k -= 1
        if k < 0:
            break


def foreach_div_scalar_list_(self, scalars=_MISSING, other=_MISSING):
    if scalars is _MISSING:
        scalars = other
    if scalars is _MISSING:
        raise TypeError("run() missing required argument: 'scalars'")

    if isinstance(self, torch.Tensor):
        tensors = [self]
    else:
        tensors = list(self)
    n = len(tensors)

    is_scalar = isinstance(scalars, (int, float, bool)) or (
        isinstance(scalars, torch.Tensor) and scalars.dim() == 0
    )
    if is_scalar:
        vals = [_scalar_value(scalars)] * n
    else:
        vals = [_scalar_value(s) for s in scalars]
        if len(vals) != n:
            raise RuntimeError(
                "_foreach_div_ expected lists of equal length, got "
                + str(n)
                + " tensors and "
                + str(len(vals))
                + " scalars"
            )

    plans = []
    for t, s in zip(tensors, vals):
        p = _plan_one(t, s)
        if p is not None:
            plans.append(p)
    if not plans:
        return None

    if not _alias_free(plans):
        # Overlapping storages: the reference applies the divisions in list
        # order, so every tensor must be finished before the next one starts.
        for p in plans:
            if p[3]:
                _launch_flat(p[0], p[1], p[2], p[0].dtype != torch.float32)
            else:
                _run_strided(p)
        return None

    groups = {}
    order = []
    for p in plans:
        if not p[3]:
            _run_strided(p)
            continue
        dt = p[0].dtype
        if dt not in groups:
            groups[dt] = []
            order.append(dt)
        groups[dt].append(p)

    for dt in order:
        g = groups[dt]
        cast = dt != torch.float32
        if len(g) == 1:
            p = g[0]
            _launch_flat(p[0], p[1], p[2], cast)
            continue
        for i in range(0, len(g), _KMAX):
            chunk = g[i : i + _KMAX]
            if len(chunk) == 1:
                p = chunk[0]
                _launch_flat(p[0], p[1], p[2], cast)
            else:
                _launch_fused([(p[0], p[1], p[2]) for p in chunk], cast)
    return None
